MultiLanguageSpellData['ru'][470197] = {name = "Благословение морского создания", additional_info = "Мгновенное действие\n[q]Дает пассивную способность передвигаться по морскому дну, находить подводные сокровища, дышать под водой и плавать значительно быстрее в водах острова Сирен и его окрестностей.\n\n Требуется надеть перстень Цирци."}
