MultiLanguageSpellData['ru'][1215727] = {name = "Классовый комплект рыцаря смерти 11.1 – лед, 2 предмета", additional_info = "Срабатывает приблизительно 10 раз(а) в минуту\n[q]Ваши заклинания и способности с некоторой вероятностью активируют \"Череду побед!\" , увеличивающую урон от \"Ледяного удара\" и \"Ледяного натиска\" на 4%. Суммируется до 6 раз. \"Ледяной удар\" и \"Ледяной натиск\" с вероятностью 7% прекращают действие \"Череды побед!\" ."}
MultiLanguageSpellData['ru'][1215728] = {name = "Классовый комплект рыцаря смерти 11.1 – нечестивость, 4 предмета", additional_info = "[q]\"Темное превращение\" дает до 10 эффектов \"Череды побед!\" . Во время действия \"Темного превращения\" эффективность \"Череды побед!\" повышается на 100%, и ее действие больше не может прерваться."}
MultiLanguageSpellData['ru'][1215729] = {name = "Классовый комплект рыцаря смерти 11.1 – лед, 4 предмета", additional_info = "[q]За каждый эффект \"Череды побед!\" ваш \"Ледяной удар\" и \"Ледяной натиск\" с вероятностью 8% применяют \"Ледяную косу\" с эффективностью 30%. Когда вы теряете \"Череду побед!\" , то впадаете в \"Кровожадное бешенство\", применяя \"Ледяную косу\" с эффективностью 100%, а ваша искусность повышается на (6 * $mastery)% на 6 сек. Кроме того, \"Ледяная коса\" наносит на 40% больше урона первой пораженной цели."}
MultiLanguageSpellData['ru'][1215730] = {name = "Классовый комплект охотника 11.1 – выживание, 2 предмета", additional_info = "Срабатывает приблизительно 10 раз(а) в минуту\n[q]Ваши заклинания и способности с некоторой вероятностью активируют \"Череду побед!\" , увеличивающую урон от \"Огнебомбы\" на 3%. Суммируется до 6 раз.\n \"Огнебомба\" с вероятностью 15% прекращает действие \"Череды побед!\" .\n(Вероятность срабатывания: 15%)"}
MultiLanguageSpellData['ru'][1215731] = {name = "Классовый комплект охотника на демонов 11.1 – истребление, 2 предмета", additional_info = "Срабатывает приблизительно 15 раз(а) в минуту\n[q]Ваши заклинания и способности с некоторой вероятностью активируют \"Череду побед!\" , увеличивающую урон от \"Танца клинков\" и \"Удара Хаоса\" на 3%. Суммируется до 10 раз. \"Танец клинков\" и \"Удар Хаоса\" с вероятностью 15% прекращают действие \"Череды побед!\" ."}
MultiLanguageSpellData['ru'][1215732] = {name = "Необходимая жертва", additional_info = "[q]\"Череда побед!\" действует еще 8 сек. после того, как ее отменяет \"Танец клинков\" или \"Удар Хаоса\".\n\n Превращение в демона жертвует все эффекты \"Череды побед!\" и повышает вероятность критического удара на 2% за каждый поглощенный эффект. Действует в течение 15 сек."}
MultiLanguageSpellData['ru'][1215733] = {name = "Массовое уничтожение", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Заклинания и способности с высокой вероятностью отмечают противников и призывают мистера Всесхватса, который совершает \" Массовое уничтожение \" и наносит ( 2489 * 1 ) ед. урона от огня, распределяемого между целью и ближайшими противниками."}
