MultiLanguageSpellData['ru'][1233093] = {name = "Коллапсирующая звезда", additional_info = "Неограниченное расстояние\nНаправляемое (Применение: 25 сек)\n[q]Адар призывает коллапсирующую звезду, которая начинает притягивать к себе игроков.\n\n Фрагменты звезды обрушиваются на землю и притягиваются к ее центру. При контакте с игроком фрагменты взрываются, нанося 1686460 ед. космического урона и применяя эффект \" Темный осадок \".\n\n Если фрагменты достигают центра звезды, они наносят всем игрокам 5270187 ед. космического урона."}
