MultiLanguageSpellData['ru'][1233546] = {name = "Рубиновый шаркун Бездны", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Концерн К'ареша приютил этого шаркуна Бездны, чтобы изучить. Он оказался удивительно выносливым ездовым зверем.\"\nТорговец:\nОм'сирик\nЗона:\nК'ареш\nЦена:\n8125"}
