MultiLanguageSpellData['ru'][1233940] = {name = "Энергетический конвертер эфириалов", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Когда уровень здоровья участника группы падает ниже 60%, появляется энергетический конвертер эфириалов, который наносит ближайшим противникам умеренный урон и провоцирует их на 6 сек. Когда провокация перестает действовать, конвертер выпускает астральную волну, восполняющую находящимся рядом союзникам 40% запаса здоровья. Эффект срабатывает не чаще раза в 2 мин. Когда вы убиваете противников, время восстановления эффекта сокращается на 6 сек."}
MultiLanguageSpellData['ru'][1233941] = {name = "Бушующая Бездна", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Наносит 10 ед. урона от темной магии и снижает скорость передвижения на 20% на 6 сек."}
MultiLanguageSpellData['ru'][1233942] = {name = "Проводник попутного ветра", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Придает ускорение после выхода из боя, повышая скорость передвижения на 100% на 10 сек. Эффект постепенно ослабевает. Если вы применяете защитную способность во время боя, вас окружают порывы ветра и дают щит, поглощающий урон в объеме 50% недостающего запаса здоровья. Время действия – 8 сек.\n(Восстановление: 30с)"}
MultiLanguageSpellData['ru'][1233945] = {name = "Звукоусиливающий кристалл", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Голос Бранна невероятно усиливается тайной магией, и его слова могут дать участникам группы различные положительные эффекты."}
MultiLanguageSpellData['ru'][1233946] = {name = "Побитая эгида", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Пока эгида используется, урон и сила исцеления участников группы увеличиваются на 12%. Раз в 10 сек. во время боя вы и Бранн восполняете здоровье в объеме 20% урона, полученного за это время.\n\n Если игрок погибает, после воскрешения эгида уменьшает получаемый им урон на 4% и усиливает получаемое исцеление на 5%, но уменьшает наносимый урон и силу творимого исцеления на 4%. Суммируется до 3 раз."}
