MultiLanguageSpellData['ru'][1234283] = {name = "Вечный диск Нарана", additional_info = "[q]Способность артефакта\n\n Вы бросаете диск чародейской энергии, который летит по дуге, а потом возвращается обратно.\n\n \" Вечный диск Нарана \" наносит [(1930% [Attack/Spell Power])] ед. урона от тайной магии противникам на своем пути.\n\n Перехватите возвращающийся диск, чтобы получить щит и бросить диск снова. Максимальное количество дополнительных бросков – 2."}
MultiLanguageSpellData['ru'][1234286] = {name = "Стойкость Крутогорья", additional_info = "[q]Повышает уровень способности \" Стойкость Крутогорья \" еще на 1.\n\n Стойкость Крутогорья\nРаз в 12 сек. вы начинаете накапливать эффект \" Стойкость \" в объеме 3% получаемого урона. Спустя 8 сек. \" Стойкость \" превращается в защитный барьер, который в течение 4 сек. поглощает урон в объеме, равном накопленному ресурсу."}
