MultiLanguageSpellData['ru'][1236128] = {name = "Статический заряд", additional_info = "[q]Заклинания и способности с некоторой вероятностью дают вам \"Статический заряд\", повышающий универсальность на ( 14 * 20) на 30 сек. Каждое последующее заклинание или способность уменьшает эту прибавку на 5%."}
MultiLanguageSpellData['ru'][1236129] = {name = "Электрический поток", additional_info = "[q]В начале боя вы получаете эффект \"Электрический поток\", повышающий искусность на 8 раз в 2 сек. Максимальный бонус – (12 * 8 ) через 24 сек. После достижения максимального бонуса эффект сбрасывается, и цикл начинается заново."}
MultiLanguageSpellData['ru'][1236130] = {name = "Сковывающее копье", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Таа'бат бросает в цели чародейские копья, наносящие игрокам в радиусе 8 м 2424449 ед. урона от тайной магии и связывающие пораженных игроков.\n\n Связь наносит 606112 ед. урона от тайной магии раз в 1 сек. и снижает скорость передвижения на 50%. Эффект усиливается раз в 5 сек. до тех пор, пока копье не будет уничтожено. Эффект суммируется."}
MultiLanguageSpellData['ru'][1236132] = {name = "Заряженное прикосновение", additional_info = "[q]Ваши исцеляющие эффекты с некоторой вероятностью выпускают искру, которая восполняет 1766 ед. здоровья цели с наименьшим уровнем здоровья в радиусе 40 м."}
MultiLanguageSpellData['ru'][1236133] = {name = "Косноязычие Санктуария", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Принуждает ближайших противников говорить на языке Санктуария, что снижает скорость применения заклинаний на 10% на до отмены."}
MultiLanguageSpellData['ru'][1236134] = {name = "Энергетический щит", additional_info = "[q]При получении урона вы с некоторой вероятностью получаете \"Энергетический щит титанов\", поглощающий до 3662 ед. урона. Время действия – 10 сек. По окончании времени действия щит взрывается и наносит урон от тайной магии в объеме 30% оставшегося запаса прочности, распределяемый между противниками в радиусе 8 м."}
MultiLanguageSpellData['ru'][1236135] = {name = "Заряженный кристалл", additional_info = "[q]Заклинания и атаки с некоторой вероятностью выпускают в цель \"Энергетический заряд\", который наносит 965 ед. урона от сил природы, распределяемого между целями в радиусе 8 м."}
