MultiLanguageSpellData['ru'][1237033] = {name = "Электрический заряд", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Заклинания и атаки с некоторой вероятностью выпускают в цель \"Энергетический заряд\", который наносит 965 ед. урона от сил природы, распределяемого между целями в радиусе 8 м."}
MultiLanguageSpellData['ru'][1237036] = {name = "Приказ отряду", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Совершая \"Глубокий вдох\" и еще в течение до отмены. после этого, вы возглавляете отряд из 2 драктиров, применяющих против ваших целей \"Дезинтеграцию\" и \"Лазурный удар\"."}
