MultiLanguageSpellData['ru'][1251545] = {name = "Астральная жатва", additional_info = "Мгновенное действие\nСрабатывает приблизительно 2 раз(а) в минуту\n[q]Наносящие урон заклинания и способности с некоторой вероятностью концентрируют рассеянную в воздухе энергию и наносят урон от тайной магии, распределяемый между целью и ближайшими противниками. Наносит на 20% больше урона противникам, уровень здоровья которых ниже 35%.\n(Восстановление: 100мс)"}
MultiLanguageSpellData['ru'][1251549] = {name = "Астральное восстановление", additional_info = "Мгновенное действие\nСрабатывает приблизительно 2 раз(а) в минуту\n[q]Благотворные заклинания и способности с некоторой вероятностью активируют дремлющую энергию и восполняют раненому союзнику здоровье. Избыточное исцеление преобразуется в поглощающий урон щит.\n(Восстановление: 100мс)"}
